#!/usr/bin/env node
// Builds the SQL that loads the HTA list into public.hta_entries.
//
//   node supabase/scripts/hta/build-seed.mjs [path/to/hta.csv]
//
// Default CSV: ~/Library/Mobile Documents/com~apple~CloudDocs/Sown/Reference/
//              hta_potentially_harmful_plants_2022.csv
// Writes:      supabase/seed/hta_entries.local.sql  (git-ignored)
//
// The HTA list is HTA copyright: never commit the CSV or the generated SQL.
// Paste the generated file into the Supabase SQL editor and run it. It is
// safe to run again: existing rows are updated, not duplicated.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { homedir } from 'node:os'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const DEFAULT_CSV = join(homedir(), 'Library/Mobile Documents/com~apple~CloudDocs/Sown/Reference',
  'hta_potentially_harmful_plants_2022.csv')
const here = dirname(fileURLToPath(import.meta.url))
const OUT = join(here, '../../seed/hta_entries.local.sql')

const PETS = ['dogs', 'cats', 'rabbits', 'rodents', 'tortoises', 'caged_birds', 'poultry']
const STATUS = { hta_a: 'hta_a', hta_b: 'hta_b', hta_c: 'hta_c', hta_bulb_or_fruit: 'hta_bulb_or_fruit_label' }

// ── Minimal CSV parser (quoted fields, doubled quotes, CRLF) ──
function parseCsv(text) {
  const rows = []
  let row = [], field = '', quoted = false
  for (let i = 0; i < text.length; i++) {
    const c = text[i]
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++ }
      else if (c === '"') quoted = false
      else field += c
    } else if (c === '"') quoted = true
    else if (c === ',') { row.push(field); field = '' }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++
      row.push(field); rows.push(row); row = []; field = ''
    } else field += c
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row) }
  const [header, ...data] = rows.filter(r => r.some(v => v !== ''))
  return data.map(r => Object.fromEntries(header.map((h, i) => [h.replace(/^﻿/, ''), r[i] ?? ''])))
}

// ── SQL literals ──
const lit = (v) => (v === null || v === undefined || v === '') ? 'null' : `'${String(v).replace(/'/g, "''")}'`
const bool = (v, required = false) => v === 'yes' ? 'true' : v === 'no' ? 'false' : (required ? 'false' : 'null')
const arr = (items, type = 'text') => {
  const list = items.map(s => s.trim()).filter(Boolean)
  return list.length ? `array[${list.map(lit).join(', ')}]::${type}[]` : 'null'
}
const list = (v, sep) => (v ? v.split(sep) : [])

function pets(v) {
  if (!v) return 'null'
  const words = v.split(';').map(s => s.trim()).filter(Boolean)
  const kinds = words.includes('all pets') ? PETS : words.map(w => w.replace(/ /g, '_'))
  const unknown = kinds.filter(k => !PETS.includes(k))
  if (unknown.length) throw new Error(`Unknown pet value(s): ${unknown.join(', ')}`)
  return arr(kinds, 'public.pet_kind')
}

function status(v) {
  if (!v) return 'null'
  if (!STATUS[v]) throw new Error(`Unknown safety_status: ${v}`)
  return `${lit(STATUS[v])}::public.safety_status`
}

// ── Build ──
const csvPath = process.argv[2] || DEFAULT_CSV
const rows = parseCsv(readFileSync(csvPath, 'utf8'))
if (rows.length === 0) throw new Error('No rows found in the CSV')

const values = rows.map(r => `(${[
  lit(r.hta_ref), lit(r.genus), lit(r.taxon), lit(r.hta_condition),
  arr(list(r.synonyms, ',')),
  arr(list(r.see_also, / and /)),
  bool(r.is_cross_reference, true),
  arr(list(r.common_names, ',')),
  status(r.safety_status),
  bool(r.specialist_list, true),
  lit(r.standard_label),
  r.harmful_to ? `${lit(r.harmful_to)}::public.harmful_to` : 'null',
  pets(r.pets_affected),
  bool(r.harmful_if_eaten), bool(r.skin_irritant),
  lit(r.label_wording_growing), lit(r.label_wording_bulbs), lit(r.affects_as_printed),
  bool(r.more_than_one_label_applies, true),
  lit(r.hta_category_as_printed),
  r.source_page ? String(parseInt(r.source_page, 10)) : 'null',
  lit(r.scientific_name_as_printed), lit(r.hta_edition),
].join(', ')})`)

const columns = ['hta_ref', 'genus', 'taxon', 'hta_condition', 'synonyms', 'see_also', 'is_cross_reference',
  'common_names', 'safety_status', 'specialist_list', 'standard_label', 'harmful_to', 'pets_affected',
  'harmful_if_eaten', 'skin_irritant', 'label_wording_growing', 'label_wording_bulbs', 'affects_as_printed',
  'more_than_one_label_applies', 'hta_category_as_printed', 'source_page', 'scientific_name_as_printed', 'hta_edition']

const sql = `-- HTA Guide to Potentially Harmful Plants: ${rows.length} entries.
-- Generated by supabase/scripts/hta/build-seed.mjs. HTA copyright: do not commit.
begin;

insert into public.hta_entries (${columns.join(', ')})
values
${values.join(',\n')}
on conflict (hta_ref) do update set
${columns.filter(c => c !== 'hta_ref').map(c => `  ${c} = excluded.${c}`).join(',\n')};

commit;

select count(*) as hta_entries_loaded from public.hta_entries;
`

mkdirSync(dirname(OUT), { recursive: true })
writeFileSync(OUT, sql)
console.log(`Wrote ${rows.length} HTA entries to ${OUT}`)
